exercises.solution:
export function binarySearchSteps(n) {
  let steps = 0;
  let span = n;
  while (span > 0) {
    span = Math.floor(span / 2);
    steps += 1;
  }
  return steps;
}

export function stepsSaved(n) {
  return n - binarySearchSteps(n);
}

