exercises.solution:
export function totalCopies(finalCapacity) {
  let copies = 0;
  for (let cap = 1; cap < finalCapacity; cap *= 2) {
    copies += cap;
  }
  return copies;
}

export function totalWrites(finalCapacity) {
  return finalCapacity + totalCopies(finalCapacity);
}
